:root{color-scheme:light;--background:#fff;--foreground:#171717;--muted:#626262;--panel:#fff;--subtle:#f7f7f9;--border:#dedee5;--primary:#4c2ab6;--primary-text:#fff;--danger:#b42318;--success:#166534;--radius:.5rem;font-family:ui-sans-serif,system-ui,sans-serif;font-size:16px}
html[data-theme=dark]{color-scheme:dark;--background:#17171b;--foreground:#f5f5f5;--muted:#b5b5c0;--panel:#202026;--subtle:#292930;--border:#454550;--primary:#b6a0ff;--primary-text:#201147;--danger:#ffb4ab;--success:#86efac}
@media(prefers-color-scheme:dark){html[data-theme=system]{color-scheme:dark;--background:#17171b;--foreground:#f5f5f5;--muted:#b5b5c0;--panel:#202026;--subtle:#292930;--border:#454550;--primary:#b6a0ff;--primary-text:#201147;--danger:#ffb4ab;--success:#86efac}}
*{box-sizing:border-box}html{scrollbar-gutter:stable;scrollbar-color:var(--muted) var(--subtle);scrollbar-width:auto}body{margin:0;background:var(--background);color:var(--foreground);line-height:1.5}a{color:var(--primary);text-underline-offset:.2em}button,input{font:inherit}button,a,input{touch-action:manipulation}:focus-visible{outline:3px solid var(--primary);outline-offset:3px}.topbar{display:flex;align-items:center;gap:1.5rem;padding:1rem 2rem;border-bottom:1px solid var(--border);min-height:4.5rem;background:var(--panel)}.brand{font-size:1.15rem;font-weight:750;color:var(--foreground);text-decoration:none}.module-name{border-left:1px solid var(--border);padding-left:1.5rem;font-size:.875rem;color:var(--muted)}.back-link{margin-left:auto;font-size:.875rem}.page{max-width:76rem;margin:auto;padding:1.75rem 2rem 4rem}.breadcrumbs{display:flex;flex-wrap:wrap;gap:.7rem;font-size:.875rem;color:var(--muted);margin-bottom:2rem}.page-heading{display:flex;justify-content:space-between;align-items:center;gap:1.5rem;margin-bottom:1.5rem}h1{font-size:1.85rem;letter-spacing:-.035em;line-height:1.2;margin:0 0 .5rem;font-weight:650}h2{font-size:1.05rem;line-height:1.35;margin:0 0 .5rem;font-weight:650}p{margin:0 0 .75rem}.muted,.help{color:var(--muted)}.button{display:inline-flex;align-items:center;justify-content:center;min-height:2.65rem;gap:.5rem;padding:.55rem 1rem;border:1px solid transparent;border-radius:var(--radius);font-weight:600;font-size:.875rem;text-decoration:none;cursor:pointer;white-space:nowrap}.primary{background:var(--primary);color:var(--primary-text)}.secondary{background:var(--panel);border-color:var(--border);color:var(--foreground)}.button:hover{filter:brightness(.94)}.button:disabled{opacity:.65;cursor:wait}.button[type=submit]{min-width:10rem}.notice{padding:1rem 1.15rem;background:var(--subtle);border:1px solid var(--border);border-radius:var(--radius);margin-bottom:1.5rem;font-size:.9rem}.notice p:last-child{margin-bottom:0}.notice.success{border-left:4px solid var(--success)}.notice.error{border-left:4px solid var(--danger)}.panel{background:var(--panel);border:1px solid var(--border);border-radius:var(--radius)}.empty{padding:3rem 1.5rem;text-align:center}.empty p{max-width:32rem;margin:.75rem auto 1.5rem}.empty-symbol{display:block;font-size:2.5rem;color:var(--primary);line-height:1;margin-bottom:1rem}.table-wrap{overflow-x:auto;scrollbar-color:var(--muted) var(--subtle)}table{border-collapse:collapse;width:100%;text-align:left;font-size:.875rem}th,td{padding:1rem;vertical-align:top;border-bottom:1px solid var(--border);overflow-wrap:anywhere}thead{background:var(--subtle);color:var(--muted)}thead th{font-weight:550}tbody tr:last-child>*{border-bottom:0}tbody th{min-width:10rem;font-weight:600}code{font-family:ui-monospace,monospace;font-size:.82rem}.badge{display:inline-block;white-space:nowrap;border:1px solid var(--border);border-radius:2rem;padding:.15rem .65rem;background:var(--subtle);font-size:.75rem;font-weight:600}.badge.enabled{color:var(--success)}.edit-link{font-weight:600}.pagination{display:flex;justify-content:flex-end;align-items:center;gap:1rem;margin-top:1.5rem;font-size:.875rem}.form-section{display:grid;grid-template-columns:minmax(14rem,1fr) minmax(0,2fr);gap:2rem;padding:1.5rem;margin-bottom:1.25rem}.section-heading p{font-size:.875rem;max-width:25rem}.fields{min-width:0}.field{margin-bottom:.75rem}.field:last-child{margin-bottom:0}.field label{display:block;font-size:.875rem;font-weight:600;margin-bottom:.45rem}.required{font-size:.7rem;font-weight:400;color:var(--muted);margin-left:.5rem}.input-row{display:flex;gap:.6rem;align-items:flex-start}.field input{min-width:0;width:100%;min-height:2.65rem;padding:.6rem .75rem;border:1px solid var(--border);border-radius:var(--radius);background:var(--background);color:var(--foreground);font-size:.9rem}.field input[type=file]{font-size:.8rem;padding:.55rem}.field input::file-selector-button{margin-right:.75rem;font:inherit;border:0;background:var(--subtle);color:var(--foreground);padding:.25rem .5rem;border-radius:.25rem;cursor:pointer}.field input[aria-invalid=true]{border-color:var(--danger)}.help{font-size:.8rem;margin:.4rem 0 0;overflow-wrap:anywhere}.field-error{color:var(--danger);font-size:.8rem;margin:.35rem 0 0}.field-error:empty{margin:0}.field-pair{display:grid;grid-template-columns:minmax(0,1fr) 7rem;gap:1rem}.checkbox-label{display:flex;align-items:center;gap:.65rem;font-weight:550}.checkbox-label input{width:1.15rem;height:1.15rem;accent-color:var(--primary)}.actions{display:flex;gap:.75rem;justify-content:flex-end;flex-wrap:wrap}.form-actions{margin-top:1.5rem}dialog{max-width:30rem;width:calc(100% - 2rem);padding:1.5rem;border:1px solid var(--border);border-radius:var(--radius);background:var(--panel);color:var(--foreground)}dialog::backdrop{background:#0008}dialog p{color:var(--muted);margin:1rem 0 1.5rem}.sr-only,.skip-link:not(:focus){position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.skip-link:focus{position:fixed;top:.5rem;left:.5rem;background:var(--panel);padding:.7rem;z-index:10}
@media(max-width:700px){.topbar{padding:1rem;gap:1rem}.module-name{display:none}.page{padding:1.25rem 1rem 3rem}.page-heading{align-items:flex-start;flex-direction:column;gap:1rem}.form-section{grid-template-columns:1fr;gap:1rem;padding:1.15rem}.input-row{flex-wrap:wrap}.input-row>.button{min-height:2.5rem}.field-pair{grid-template-columns:minmax(0,1fr) 5.5rem;gap:.75rem}h1{font-size:1.6rem}.actions .button{flex:1}.breadcrumbs{margin-bottom:1.5rem}}
@media(forced-colors:active){:root{scrollbar-color:auto}.badge,.button{border:1px solid ButtonText}}
.danger-zone{margin-top:2rem;border-left:4px solid var(--danger)}.danger-zone .button{margin-top:1rem}.danger-zone code{overflow-wrap:anywhere}.danger-link{color:var(--danger)}.danger{background:var(--danger);color:var(--background);border-color:var(--danger)}
.danger-zone .section-heading{min-width:0;overflow-wrap:anywhere}
.module-nav{display:flex;flex-wrap:wrap;gap:.5rem 1.5rem;border-bottom:1px solid var(--border);margin:-.5rem 0 1.75rem;padding-bottom:.75rem;font-size:.9rem}.module-nav a{text-decoration:none;padding:.4rem 0}.module-nav a[aria-current]{font-weight:700;border-bottom:2px solid var(--primary)}.module-nav a:hover{text-decoration:underline}button:not(:disabled):active,.button:active{filter:brightness(.88)}.button:disabled:hover{filter:none}.field select{font:inherit;width:100%;min-width:0;min-height:2.8rem;padding:.6rem .75rem;border:1px solid var(--border);border-radius:var(--radius);background:var(--background);color:var(--foreground);cursor:pointer}.field select[aria-invalid=true]{border-color:var(--danger)}.search-form{display:flex;gap:.75rem;align-items:flex-start;margin-bottom:1.5rem;flex-wrap:wrap}.search-form .field{flex:1 1 16rem;margin:0}.search-form .button{margin-top:1.75rem;min-width:auto}.file-caption{display:block;font-weight:400;color:var(--muted);margin-top:.35rem}.size-cell{white-space:nowrap}.selected-backup{min-width:0;overflow-wrap:anywhere}.transfer-details{display:grid;grid-template-columns:7rem minmax(0,1fr);gap:.6rem 1rem;margin:0;font-size:.9rem}.transfer-details dt{color:var(--muted)}.transfer-details dd{margin:0;overflow-wrap:anywhere}.progress-label{display:block;font-size:.875rem;font-weight:600;margin-bottom:.75rem}progress{display:block;width:100%;height:.75rem;accent-color:var(--primary);border:0;border-radius:var(--radius);overflow:hidden;background:var(--subtle)}progress::-moz-progress-bar{background:var(--primary)}progress::-webkit-progress-bar{background:var(--subtle)}progress::-webkit-progress-value{background:var(--primary)}.refresh-state{min-height:3rem;padding-top:.4rem}.pagination{flex-wrap:wrap}.button:disabled{cursor:not-allowed}
@media(max-width:700px){.module-nav{gap:1rem}.transfer-details{grid-template-columns:1fr;gap:.25rem}.transfer-details dd{margin-bottom:.6rem}.search-form .field{flex-basis:100%}.search-form .button{margin-top:0}}

.transfer-duration{min-height:1.5em;font-variant-numeric:tabular-nums;white-space:nowrap}
